var QUESTOES_INTERPRETACAOTEXTOS = [{"id":2405,"enunciado":"No encerramento do Texto 1, ao empregar a expressão “Pronto — virgulei”, o autor","opcoes":["retoma sua crítica em chave normativa, defendendo um controle mais rígido da linguagem.","conclui sua crítica em tom categórico, confirmando sua posição de certeza.","relativiza sua crítica, afastando dela o caráter de verdade definitiva.","reforça sua crítica aos clichês, acentuando seu tom de reprovação."],"correta":2,"explicacao":"Gabarito: <strong>relativiza sua crítica, afastando dela o caráter de verdade definitiva.</strong>.","banca":"IV - UFG","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":3175,"enunciado":"Com referência ao texto e a seus aspectos linguísticos e gramaticais, julgue o item seguinte. Na linha 2, o termo “&#8209;los”, em “curá&#8209;los”, retoma o termo antecedente “os doentes”, da mesma forma que, na linha 16, o termo “&#8209;la” retoma “a alma”.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":4005,"enunciado":"Preencha as lacunas e assinale a alternativa correta. No interior do Brasil, ainda se podem ver ________________ da luta entre mouros e cristãos. O evento costuma ocorrer por ocasião das Festas Juninas ou da Festa do Divino. É precedido de missa e procissão e concluído com jogos de equitação, confraternização e fogos de artifício. Às vezes, recebe o nome de _____________ e, em geral, participa do que se convencionou chamar Cavalhadas. O ritual participa das tradições _______________.","opcoes":["audições / banquete / modernas","dramatizações / chegança / folclóricas","leituras / corrida / institucionais","celebrações / folclore / contemporâneas","representações / torneio / antigas"],"correta":1,"explicacao":"Gabarito: <strong>dramatizações / chegança / folclóricas</strong>.","banca":"INSTITUTO AOCP","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":4075,"enunciado":"No trecho “No entanto, a febre amarela silvestre não é erradicável, já que possui uma circulação natural entre primatas das florestas tropicais.”, a palavra “primatas” foi utilizada em referência ao grupo de","opcoes":["baleias, morcegos e bois.","ratos, gatos e saguis.","tigres, girafas e lêmures.","cães, gatos e cavalos.","macacos, gorilas e chimpanzés."],"correta":4,"explicacao":"Gabarito: <strong>macacos, gorilas e chimpanzés.</strong>.","banca":"Quadrix","ano":2025,"temas_relacionados":["interpretacaoTextos"]},{"id":4271,"enunciado":"Marque a alternativa em que há um caso de ambiguidade.","opcoes":["O gerente revisou o contrato e comunicou a mudança ao cliente.","Os candidatos discutiram o projeto antes da reunião.","A empresa entregou os documentos assinados ontem.","O engenheiro analisou os relatórios financeiros da construtora.","Os supervisores acompanharam o andamento da produção."],"correta":2,"explicacao":"Gabarito: <strong>A empresa entregou os documentos assinados ontem.</strong>.","banca":"CETREDE","ano":2025,"temas_relacionados":["interpretacaoTextos"]},{"id":4695,"enunciado":"Assinale a alternativa que indica o sentido correto da palavra “prole” (l. 03).","opcoes":["Avós.","Filhos.","Pais.","Tios.","Primos."],"correta":1,"explicacao":"Gabarito: <strong>Filhos.</strong>.","banca":"FUNDATEC","ano":2024,"temas_relacionados":["interpretacaoTextos"]},{"id":4805,"enunciado":"Assinale a alternativa que apresenta, na ordem correta, os substantivos coletivos de: porcos, macacos, filhos, camelos e borboletas.","opcoes":["Panapaná, cáfila, prole, capela e vara.","Capela, prole, vara, panapaná e cáfila.","Vara, capela, prole, cáfila e panapaná.","Vara, cáfila, prole, capela e panapaná."],"correta":2,"explicacao":"Gabarito: <strong>Vara, capela, prole, cáfila e panapaná.</strong>.","banca":"MPE-GO","ano":2024,"temas_relacionados":["interpretacaoTextos"]},{"id":5383,"enunciado":"A exclusão do artigo “o”, em “o país” (segundo período do quinto parágrafo) mantém a correção gramatical e o sentido do texto.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Qconcursos","ano":2023,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":6288,"enunciado":"No trecho “uma dupla inseparável” (1º parágrafo), a palavra destacada pode ser substituída, sem mudar o sentido do texto, por:","opcoes":["indissociável.","distante.","diferente.","indiscutível."],"correta":0,"explicacao":"Gabarito: <strong>indissociável.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":6326,"enunciado":"Considerando os trechos a seguir, assinale a alternativa em que a substituição da palavra sublinhada NÃO mantém o sentido do texto original:","opcoes":["É uma mistura dos ingredientes do tratamento da folha” É uma combinação dos ingredientes do tratamento da folha.","A água usada na fabricação do papel não evapora por completo” A água usada na fabricação do papel não evapora completamente.","E é claro: o aroma depende do processo pelo qual ele passou” E é claro: o aroma depende do processo pelo qual aquela passou.","Dois livros que usam papéis diferentes, por exemplo, não têm o mesmo cheiro” Dois livros que usam papéis distintos, por exemplo, não têm o mesmo cheiro."],"correta":2,"explicacao":"Gabarito: <strong>E é claro: o aroma depende do processo pelo qual ele passou” E é claro: o aroma depende do processo pelo qual aquela passou.</strong>.","banca":"Prefeitura de Chopinzinho - PR","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":6355,"enunciado":"Julgue o seguinte item, referente às estruturas linguísticas e ao vocabulário empregados no texto CG7A1. No trecho \"impactos ambientais adversos gerados pelas atividades administrativas\" (último parágrafo), o vocábulo \"adversos\" tem o mesmo sentido de prejudiciais.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":6411,"enunciado":"No texto, a palavra “simples” (l. 02) tem o mesmo sentido de:","opcoes":["Elaborada.","Diferente.","Fácil.","Grandiosa."],"correta":2,"explicacao":"Gabarito: <strong>Fácil.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":6470,"enunciado":"No texto, a palavra “falaciosa” (linha 64) veicula o mesmo sentido de","opcoes":["audaciosa.","corajosa.","perniciosa.","morosa.","mentirosa."],"correta":4,"explicacao":"Gabarito: <strong>mentirosa.</strong>.","banca":"Ibest","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":6651,"enunciado":"No trecho “Ela me pediu agora há pouco todas as suas informações. E já te bloqueou.”, a palavra “ela” retoma a:","opcoes":["moça observada pelo narrador","inteligência artificial citada no texto","câmera do celular mencionada antes","frase de autoajuda publicada no insta"],"correta":0,"explicacao":"Gabarito: <strong>moça observada pelo narrador</strong>.","banca":"SELECON","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":6659,"enunciado":"No trecho \"É como se o tempo tivesse decidido botar nelas sua própria caligrafia.\" (2º parágrafo), o termo destacado mantém relação coesiva anafórica com a expressão:","opcoes":["pequena Cíntia.","rochas sedimentares.","faixas de cores.","grandes livros.","restos de outras rochas."],"correta":1,"explicacao":"Gabarito: <strong>rochas sedimentares.</strong>.","banca":"FAFIPA","ano":2026,"temas_relacionados":["interpretacaoTextos","ortografia"]},{"id":6670,"enunciado":"Leia o texto a seguir, observando as palavras em destaque. Lançamento do Livro “A Nossa Oktoberfest Blumenau” celebra 40 anos da maior festa alemã das Américas 2 de fevereiro, 2026 A Oktoberfest Blumenau nasceu de histórias, pessoas e encontros que, ao longo de quatro décadas, transformaram a festa em um dos maiores símbolos culturais do Brasil. Preservar essa trajetória e, ao mesmo tempo, olhar para o futuro, foi a proposta do lançamento do livro “A Nossa Oktoberfest Blumenau”, que teve como produtor, o publicitário José Geraldo Reis Pfau e que ocorreu nesta segunda-feira, dia 2, no Frohsinn. A obra reúne entrevistas com personagens que fizeram parte da construção da festa ao longo dos anos, registrando diferentes olhares, desafios e conquistas que ajudaram a consolidar a Oktoberfest como a festa mais alemã das Américas. As histórias apresentadas no livro dão voz a quem viveu e ajudou a escrever cada capítulo dessa trajetória. https://oktoberfestblumenau.com.br/2026/02/02/lancamento-do-livro-a-nossaoktoberfest-blumenaucelebra-40-anos-da-maior-festa-alema-das-americas/ Em um texto, pronomes podem funcionar como importantes mecanismos de coesão, ao retomarem termos anteriores e evitarem repetições desnecessárias. Considerando o uso dos pronomes relativos marcados no texto, assinale a opção em que se identifica corretamente o elemento retomado pelo pronome destacado.","opcoes":["“que (...) transformaram a festa em um dos maiores símbolos culturais do Brasil.” - retoma “histórias, pessoas e encontros”.","“que teve como produtor, o publicitário José Geraldo Reis Pfau” - retoma “A Oktoberfest Blumenau”.","“que ocorreu nesta segunda-feira, dia 2, no Frohsinn.” - retoma “José Geraldo Reis Pfau”.","“que fizeram parte da construção da festa ao longo dos anos” - retoma “entrevistas”.","“que ajudaram a consolidar a Oktoberfest como a festa mais alemã das Américas.” - retoma “personagens”."],"correta":0,"explicacao":"Gabarito: <strong>“que (...) transformaram a festa em um dos maiores símbolos culturais do Brasil.” - retoma “histórias, pessoas e encontros”.</strong>.","banca":"FGV","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":6673,"enunciado":"O termo “elas”, retoma:","opcoes":["Vacinas.","Classes mais altas.","Instituições públicas.","Famílias de baixa renda."],"correta":1,"explicacao":"Gabarito: <strong>Classes mais altas.</strong>.","banca":"UNIFAL-MG","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":6692,"enunciado":"Considerando os mecanismos de coesão empregados no texto CG1A1 e seus sentidos, assinale a opção correta.","opcoes":["No último parágrafo, o termo “Isso” refere-se à “formação contínua dos operadores do direito”, mencionada posteriormente.","No terceiro parágrafo, a forma pronominal “Esta” tem função catafórica, pois prenuncia uma informação apresentada posteriormente no texto.","No último parágrafo, o termo “que”, em “É crucial estabelecer políticas públicas que incentivem a inovação, mas que também delimitem o campo de atuação da IA”, retoma, em suas duas ocorrências, a expressão “políticas públicas\".","No primeiro parágrafo, o segmento “dessa tecnologia” retoma a expressão “era digital”.","No segundo parágrafo, o termo “ela”, em “ela desafia noções tradicionais”, retoma o segmento “linguagem natural e robótica”."],"correta":2,"explicacao":"Gabarito: <strong>No último parágrafo, o termo “que”, em “É crucial estabelecer políticas públicas que incentivem a inovação, mas que também delimitem o campo de atuação da IA”, retoma, em suas duas ocorrências, a expressão “políticas públicas\".</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":6700,"enunciado":"No trecho \"Isso aumenta o risco de erros de dosagem, efeitos colaterais e toxicidade\", o termo destacado retoma:","opcoes":["o uso de formulações destinadas a crianças mais velhas em bebês.","a administração de medicamentos inadequados em adultos.","os efeitos colaterais e toxicidade.","a ausência de vacinas contra a malária no Brasil.","a falta de diagnóstico precoce da malária."],"correta":0,"explicacao":"Gabarito: <strong>o uso de formulações destinadas a crianças mais velhas em bebês.</strong>.","banca":"FAFIPA","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":6723,"enunciado":"\"...minha tempestade não tenha me colocado exatamente em um estado zen.\" O uso da primeira pessoa no trecho contribui para:","opcoes":["Substituir os dados científicos por impressões subjetivas, enriquecendo o argumento.","Enfraquecer a credibilidade das informações técnicas.","Eliminar a objetividade do texto, tornando-o exclusivamente opinativo.","Introduzir uma vivência pessoal que aproxima o leitor e complementa as informaç"],"correta":3,"explicacao":"Gabarito: <strong>Introduzir uma vivência pessoal que aproxima o leitor e complementa as informaç</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":6724,"enunciado":"\"...minha tempestade não tenha me colocado exatamente em um estado zen.\" O uso da primeira pessoa no trecho contribui para:","opcoes":["Substituir os dados científicos por impressões subjetivas, enriquecendo o argumento.","Introduzir uma vivência pessoal que aproxima o leitor e complementa as informações.","Enfraquecer a credibilidade das informações técnicas.","Eliminar a objetividade do texto, tornando-o exclusivamente opinativo."],"correta":1,"explicacao":"Gabarito: <strong>Introduzir uma vivência pessoal que aproxima o leitor e complementa as informações.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":6742,"enunciado":"\"...minha tempestade não tenha me colocado exatamente em um estado zen.\" O uso da primeira pessoa no trecho contribui para:","opcoes":["Introduzir uma vivência pessoal que aproxima o leitor e complementa as informações","Eliminar a objetividade do texto, tornando-o exclusivamente opinativo","Enfraquecer a credibilidade das informações técnicas.","Substituir os dados científicos por impressões subjetivas, enriquecendo o argumento."],"correta":0,"explicacao":"Gabarito: <strong>Introduzir uma vivência pessoal que aproxima o leitor e complementa as informações</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":6769,"enunciado":"Em “Eles podem imitar outros animais e podem até construir vocabulários de palavras humanas.”, o verbo destacado expressa:","opcoes":["Dificuldade.","Hipótese.","Incapacidade.","Capacidade."],"correta":3,"explicacao":"Gabarito: <strong>Capacidade.</strong>.","banca":"CONSULPAM","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":6903,"enunciado":"A sequência de verbos apresentados em primeira pessoa do singular no terceiro quadrinho tem por objetivo","opcoes":["caracterizar os diversos tipos de amor existentes nas relações humanas.","apresentar termos equivalentes à existência do amor romântico idealizado.","desmistificar a possibilidade de as pessoas encontrarem o verdadeiro amor.","desviar a atenção de uma das personagens sobre uma ideia conservadora do amor."],"correta":2,"explicacao":"Gabarito: <strong>desmistificar a possibilidade de as pessoas encontrarem o verdadeiro amor.</strong>.","banca":"IV - UFG","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":7355,"enunciado":"Assinale a alternativa em que o elemento destacado faz referência a algo apresentado posteriormente dentro do enunciado.","opcoes":["Ontem acabei conhecendo os seus pais. Eles são muito simpáticos e agradáveis.","Exijo de você apenas uma coisa: que se dedique com muita afeição as suas tarefas.","Eu já lhe disse que você deve conferir cada item, e você não está fazendo isso como deve.","A face oculta da Lua é a parte do satélite natural que nunca se mostra para nos.","Seja prudente e atento; essas características lhe ensinam a viver bem."],"correta":1,"explicacao":"Gabarito: <strong>Exijo de você apenas uma coisa: que se dedique com muita afeição as suas tarefas.</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":7372,"enunciado":"As palavras sublinhadas abaixo retomam, respectivamente: As praias estão sempre lotadas nessas épocas de fim e início de ano. Elas se enchem de banhistas loucos por descanso e paz. Afinal, eles passam o ano inteiro trabalhando.","opcoes":["Nessas épocas | loucos.","Lotadas | descanso e paz.","As praias | banhistas.","As praias | fim e início de ano."],"correta":2,"explicacao":"Gabarito: <strong>As praias | banhistas.</strong>.","banca":"OBJETIVA","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":7378,"enunciado":"No trecho Os valores ainda são distantes da realidade do país, que tinha, em 2022, 95,6% das residências abastecidas..., o termo sublinhado é um pronome relativo. Diante disso, assinale a alternativa que indica a sua classificação sintática e o seu referente CORRETOS nesse período.","opcoes":["Exerce função de sujeito simples e retoma o substantivo país.","Exerce função de objeto direto e retoma o substantivo realidade.","Exerce função de sujeito e retoma a expressão Os valores.","Exerce função de adjunto adnominal e retoma cronologicamente o termo 2022."],"correta":0,"explicacao":"Gabarito: <strong>Exerce função de sujeito simples e retoma o substantivo país.</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":7392,"enunciado":"Assinale a alternativa cujo elemento destacado faz referência a algo apresentado posteriormente no enunciado.","opcoes":["Conheci a sua prima ontem, e achei essa menina muito bacana.","Pedi para você ir à padaria e comprar leite, mas você não o fez.","Ele chega sempre atrasado para as reuniões, e isso ainda vai lhe custar caro.","Nunca esqueça isto: ame a si próprio, mas primeiro cuide dos seus próximos.","Juliana e Andreia – são elas que vão nos representar no campeonato nacional."],"correta":3,"explicacao":"Gabarito: <strong>Nunca esqueça isto: ame a si próprio, mas primeiro cuide dos seus próximos.</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":7400,"enunciado":"No trecho retirado do texto “Um dos enigmas mais persistentes e importantes de toda a física espacial é: o que é matéria escura? Esse material invisível e misterioso”, o vocábulo “esse” retoma:","opcoes":["“matéria escura”.","“física espacial”.","“enigma”.","“persistente e importante”."],"correta":0,"explicacao":"Gabarito: <strong>“matéria escura”.</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":7405,"enunciado":"A expressão “a primeira” na linha 12 retoma qual palavra ou expressão?","opcoes":["“a física do fenômeno” (l. 11).","“a biologia” (l. 11).","“a manobra” (l. 10).","“a coluna vertebral” (l. 13)."],"correta":0,"explicacao":"Gabarito: <strong>“a física do fenômeno” (l. 11).</strong>.","banca":"FUNDATEC","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":7417,"enunciado":"No período sublinhado no quarto parágrafo, os termos destacados cumprem a função de coesão referencial. Nesse sentido, identifique seus respectivos referentes sintático-semânticos no texto e assinale a alternativa CORRETA.","opcoes":["ela retoma \"a região de Pinto Bandeira\"; seus refere-se aos \"vinhos e derivados\".","ela retoma \"Companhia Vinícola Rio-Grandense S.A.\"; \"seus\" também se refere à \"Companhia Vinícola Rio-Grandense S.A.\", denotando posse em relação aos \"associados\".","\"ela\" retoma \"a Companhia Vinícola Rio-Grandense S.A.\"; \"seus\" faz referência catafórica estrita a \"pinto Bandeira\".","\"ela\" retoma a \"Companhia Vinícola Rio-Grandense S.A.\"; \"seus\" refere-se antecipadamente às \"variedades Vitis vinifera'\"."],"correta":1,"explicacao":"Gabarito: <strong>ela retoma \"Companhia Vinícola Rio-Grandense S.A.\"; \"seus\" também se refere à \"Companhia Vinícola Rio-Grandense S.A.\", denotando posse em relação aos \"associados\".</strong>.","banca":"LEGALLE Concursos","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":7432,"enunciado":"Acerca das relações coesivas estabelecidas no texto, assinale a alternativa correta.","opcoes":["O vocábulo “que”, em “que não sabe fazer uma simples regra de três” (linhas 30 e 31), retoma “médico” (linha 28).","O vocábulo “os”, em “o ensino superior os motiva” (linha 51), retoma “pessoas de baixa renda” (linhas 43 e 44).","O vocábulo “seu”, em “ter seu acesso democratizado” (linha 62), tem como referente a expressão “Outra parte” (linha 55).","O vocábulo “cujo”, em “cujo único objetivo é o lucro pelo lucro” (linhas 64 e 65), tem como referente a expressão “uma narrativa falaciosa” (linhas 63 e 64).","O vocábulo “que”, em “que a falsa inclusão” (linhas 68 e 69), retoma “A grande ironia” (linha 68)."],"correta":3,"explicacao":"Gabarito: <strong>O vocábulo “cujo”, em “cujo único objetivo é o lucro pelo lucro” (linhas 64 e 65), tem como referente a expressão “uma narrativa falaciosa” (linhas 63 e 64).</strong>.","banca":"Ibest","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":7488,"enunciado":"Assinale a alternativa em que o verbo destacado está no passado.","opcoes":["“… vai retornar ao mesmo local em uma nova função…”","“… não teve condições de pagar uma universidade…”.","“… ingressar diretamente no mercado de trabalho”.","“… já formada, ela troca de função, mas não de local de trabalho”."],"correta":1,"explicacao":"Gabarito: <strong>“… não teve condições de pagar uma universidade…”.</strong>.","banca":"VUNESP","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":7518,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o item a seguir. No período “o cuidado transcende os limites físicos do leito hospitalar para abraçar a responsabilidade sobre o ambiente onde os pacientes habitam”, a forma verbal “abraçar” é empregada em sentido denotativo, referindo&#8209;se ao ato físico de envolver algo com os braços.\nC) Certo\nE) Errado","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":7559,"enunciado":"\"...pode começar a se assemelhar a práticas de atenção plena.\" O emprego da forma verbal 'pode' indica:","opcoes":["Possibilidade, revelando cautela na afirmação.","Imposição de uma regra científica comprovada.","Certeza quanto à equivalência entre chuva e meditação.","Negação implícita do efeito relaxante."],"correta":0,"explicacao":"Gabarito: <strong>Possibilidade, revelando cautela na afirmação.</strong>.","banca":"ACCESS","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":7624,"enunciado":"CAZO. Dia mundial da água. Disponível em <https://blogdoaftm.com.br/charge-22-de-maio/> Na expressão “vamos ter que mudar\", utilizada na charge acima, mantendo o mesmo sentido, a parte destacada pode ser substituída corretamente por:","opcoes":["\"iremos\".","\"iríamos\".","\"seremos\".","\"seríamos\".","\"teremos\"."],"correta":4,"explicacao":"Gabarito: <strong>\"teremos\".</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":7664,"enunciado":"CAZO. IBGE. Disponível <https://blogdoaftm.com.br/charge-195-milhoes-debrasileiros-vivem-em-ruas-nao-pavimentadas/>. A expressão verbal “tem passado”, utilizada na fala da personagem na charge acima, indica uma ação que:","opcoes":["está começando no presente e vai continuar até o futuro.","começou no passado e continua até o momento da fala.","está sendo planejada para acontecer num futuro distante.","está sendo planejada para acontecer num futuro próximo.","depende de uma condição no passado para acontecer no futuro."],"correta":1,"explicacao":"Gabarito: <strong>começou no passado e continua até o momento da fala.</strong>.","banca":"Avança SP","ano":2026,"temas_relacionados":["interpretacaoTextos"]},{"id":7895,"enunciado":"Quando os olhos se abrem, eles as mansas meninas dos hospitais. , então, a vontade de exclamar elas: “Oh! os anjos de papel couché!...” Mas não seria prudente dirigir moças encantadoras uma exclamação assim. Em conformidade com o sentido do texto e com a norma- -padrão, as lacunas da frase devem ser preenchidas, respectivamente, com:","opcoes":["veem ... Vem ... a ... àquelas","vêm ... Veem ... à ... àquelas","vem ... Vêm ... a ... aquelas","veem ... Vem ... à ... aquelas","vêm ... Vêm ... a ... àquelas"],"correta":0,"explicacao":"Gabarito: <strong>veem ... Vem ... a ... àquelas</strong>.","banca":"VUNESP","ano":2024,"temas_relacionados":["interpretacaoTextos"]},{"id":8072,"enunciado":"Segundo o texto, o cão falou. Em seguida a mulher ficou espantada. Entre a fala do cão e o espanto da mulher, há uma relação de:","opcoes":["fato e consequência","fato e conclusão","fato e finalidade","fato e opinião","fato e causa"],"correta":0,"explicacao":"Gabarito: <strong>fato e consequência</strong>.","banca":"SELECON","ano":2024,"temas_relacionados":["interpretacaoTextos"]},{"id":18765,"enunciado":"A expressão \"Essas ansiedades\" (.11-12) retoma, no desenvolvimento do texto, as idéias do temor do que virá no futuro e a preocupação com a estabilidade dos mercados e da economia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2008,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":42379,"enunciado":"A recuperação econômica mundial, em especial em países com grandes populações como China e Índia, retoma a pressão sobre o uso dos recursos naturais do planeta, na medida em que tais países utilizam quantidades significativas de combustíveis não renováveis.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":42382,"enunciado":"A forma verbal \"descenderiam\" (L.8) poderia ser substituída, com correção gramatical e sem prejuízo para o sentido do texto, por proviriam.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":42383,"enunciado":"Pelo sentido do texto, a palavra \"juízo\" (L.7) pode ser corretamente interpretada como pensamento, opinião.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2010,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":85335,"enunciado":"O que espero, eis a resposta correta, é que sejam felizes. Ora, felicidade é coisa grandiosa. (3o parágrafo) Com a palavra grifada, o autor","opcoes":["retoma o mesmo sentido do que foi anteriormente afirmado.","exprime reserva em relação à opinião exposta na afirmativa anterior.","coloca uma alternativa possível para a afirmativa feita anteriormente.","determina uma situação em que se realiza a probabilidade antes considerada","estabelece algumas condições necessárias para a efetivação do que se afirma."],"correta":1,"explicacao":"Gabarito: <strong>exprime reserva em relação à opinião exposta na afirmativa anterior.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["interpretacaoTextos"]},{"id":85345,"enunciado":"A afirmativa correta, segundo o texto, é:","opcoes":["A organização de grupos voltados para melhorias das atividades econômicas esbarra na ausência de formação de seus componentes.","O 2o parágrafo explica claramente o significado da expressão Tecnologia Social e seu papel no desenvolvimento sustentável de comunidades.","É difícil determinar, com clareza, quais formas alternativas seriam necessárias para o desenvolvimento de comunidades.","A indefinição sobre o que seja conhecimento científico ou saber popular torna difícil a aplicação de um ou de outro nas comunidades mais pobres.","Nem sempre as experiências programadas para determinados lugares apresentam resultados satisfatórios, devido à resistência contra inovações no modo de vida local."],"correta":1,"explicacao":"Gabarito: <strong>O 2o parágrafo explica claramente o significado da expressão Tecnologia Social e seu papel no desenvolvimento sustentável de comunidades.</strong>.","banca":"FCC","ano":2011,"temas_relacionados":["interpretacaoTextos"]},{"id":133056,"enunciado":"A locução verbal “havia imprimido” (L.11-12) pode ser substituída por imprimira, sem prejuízo para a correção gramatical e para o sentido do texto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2011,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":318338,"enunciado":"Em relação às informações e estruturas linguísticas do texto acima, julgue os itens que se seguem.\n\nNo segundo parágrafo, o segmento “O órgão” (l.9) retoma, por coesão, o termo antecedente “CNJ” (l.8).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2013,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":342941,"enunciado":"Com relação à interpretação do texto e à significação das palavras nele empregadas, julgue os seguintes itens.\n\nO termo “Demais” (l.3) tem o mesmo valor que a expressão Além disso.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":342942,"enunciado":"Com relação à interpretação do texto e à significação das palavras nele empregadas, julgue os seguintes itens.\n\nDurante o período em que substituiu o administrador da repartição, Pádua foi remunerado pelo exercício dessa função.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":342944,"enunciado":"Com relação à interpretação do texto e à significação das palavras nele empregadas, julgue os seguintes itens.\n\nA palavra “fortuna”, em “Esta mudança de fortuna” (l.24), foi empregada no sentido de grande quantidade de dinheiro","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":342956,"enunciado":"Julgue os itens de 8 a 20 com relação a aspectos gramaticais e ortográficos do texto.\n\nO verbo empregado em “chegara o efetivo” (l.31) pode ser substituído pela locução verbal tinha chegado, sem prejuízo para a interpretação do texto","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2009,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":359767,"enunciado":"Com base nas ideias desenvolvidas no texto, julgue os itens a seguir.\n\nSem prejuízo para o sentido do texto, o vocábulo “onerar” (l.28) poderia ser corretamente substituído por tornar mais dispendiosa.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":377370,"enunciado":"Caso se substituísse o conectivo “mas” (l.10) por no entanto, seriam mantidos a correção gramatical e o sentido do texto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":420787,"enunciado":"Conforme o texto, D. Pedro II procurava atuar de forma a evitar que ficasse patente o exercício discricionário de seu poder.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":420790,"enunciado":"De acordo com o texto, D. Pedro II concentrava, na prática, mais poder do que a Constituição do Império lhe outorgava.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2014,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":825808,"enunciado":"Julgue o item a respeito dos sentidos do texto e de seus aspectos linguísticos.\n\nDe acordo com o texto, as consequências do atual modelo de desenvolvimento mundial são prejudiciais à vida no planeta.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":825814,"enunciado":"Julgue o item a respeito dos sentidos do texto e de seus aspectos linguísticos.\n\nA expressão “O mesmo fenômeno” (linha 11) retoma por coesão a ideia da evidência de “situações de caos aparente e de desestruturação” (linha 9).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2017,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":872742,"enunciado":"Com relação à variação linguística bem como aos sentidos e aos aspectos linguísticos do texto 6A1AAA, julgue o próximo item.\n\n\n\n\nO vocábulo aí, na contração “daí” (ℓ.15), retoma a ideia expressa no trecho “não acreditar cegamente naquilo que supõe saber” (ℓ. 14 e 15).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2018,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":933814,"enunciado":"Em relação ao texto, julgue o item a seguir.\n\n\n\n\n\nDe acordo com o texto, é importante que se entenda que o descarte de embriões para evitar o nascimento de crianças doentes é tão imoral quanto a prática do aborto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":972142,"enunciado":"Com relação às ideias e aos aspectos linguísticos e estruturais do texto, julgue o item\n\n\n\n\nConforme o texto, a qualidade de vida está intimamente relacionada com o poder aquisitivo do indivíduo.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":986754,"enunciado":"Considerando os aspectos linguísticos do texto, julgue o próximo item.\n\n\n\n\nEm “Os pesquisadores também foram ecléticos em relação aos estilos”(linhas 25 e 26), a palavra “ecléticos” foi empregada no sentido de versáteis ou flexíveis.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":989036,"enunciado":"De acordo com o texto, julgue o item a seguir.\n\n\n\n\nNo texto, que se caracteriza como dissertativo‐argumentativo, a ideia central é apresentada no primeiro parágrafo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":989037,"enunciado":"De acordo com o texto, julgue o item a seguir.\n\n\n\n\nDe acordo com o texto, pesquisas na área da psiquiatria obtiveram um grande avanço ao identificarem a relação existente entre estresse e aumento do cortisol no organismo humano.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1030859,"enunciado":"Acerca das ideias do texto, julgue o item.\n\n\n\n\nConforme o texto, a conjuntura das relações públicas perpassa, necessariamente, a ética, pois o julgamento das relações públicas decorre de seu impacto na sociedade.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1030861,"enunciado":"Julgue o item quanto às estruturas linguísticas do texto.\n\n\n\n\nO vocábulo “as” (linha 9) retoma o termo “relações públicas” (linha 8), que, por sua vez, é retomado por “profissão” (linha 10).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1033812,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o item.\n\n\n\n\nDe acordo com o texto, o aumento da expectativa de vida da população brasileira requer que o País invista mais na área da saúde.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1055640,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o iten.\n\n\nDe acordo com o texto, é produzida, no Brasil, pesquisa acadêmica em saúde de alta qualidade","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1068094,"enunciado":"Julgue o item que se segue quanto às ideias e às estruturas linguísticas do texto.\n\n\n\n\nA forma verbal “responde” é usada, na ilustração, com o mesmo sentido de retumba.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2018,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1125331,"enunciado":"No título do texto, há um processo de referenciação catafórica, pois a expressão “conclusão surpreendente” faz referência a algo que se localiza depois dela.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"INSTITUTO AOCP","ano":2018,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1176638,"enunciado":"Julgue o item em relação aos aspectos linguísticos do texto.\n\n\n\n\nA expressão “o que” (linha 45) retoma todo o segmento a partir de “burocracia” (linha 43), razão pela qual pode ser substituída por e isso, da mesma forma que “sua” (linha 45) retoma “SNBP” (linha 31).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1177779,"enunciado":"No que se refere aos aspectos linguísticos e gramaticais do texto, julgue o item .\n\n\n\n\nNo texto, o elemento “o” (linha 36) retoma o segmento “falta de sensibilidade e empatia” (linha 34).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1178285,"enunciado":"No que concerne à estruturação linguístico‐gramatical do texto, julgue o item.\n\n\n\n\n\n\n\nO vocábulo “neste” (linha 10) retoma um elemento anteriormente citado no texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1178288,"enunciado":"No que concerne à estruturação linguístico‐gramatical do texto, julgue o item.\n\n\n\n\n\n\n\nNo texto, a palavra “cujas” (linha 29) retoma “ele” (linha 29), que, por sua vez, faz referência a “mercado” (linha 27).","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1252399,"enunciado":"Com relação às ideias do texto, julgue o item.\n\n\n\n\nConforme o texto, é gritante a invisibilidade do trabalho da mulher camponesa no contexto da agricultura familiar e da segurança alimentar e nutricional.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1252405,"enunciado":"Acerca da estruturação linguística do texto, julgue o item.\n\n\n\n\nNo texto, o termo “essa” (linha 8) retoma o trecho “grande percentagem dos alimentos básicos que chegam à mesa da população” (linhas 7 e 8).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1682782,"enunciado":"Uma estrutura de centro e periferia surge, com frequência, por razões e fatores bem diversos, conforme o texto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1682793,"enunciado":"No trecho “Era como um alojamento de quartel”, o termo “como” foi empregado no sentido de conforme, para indicar que o casarão referido no período “E já estava ... Argentina.” fora construído em forma de quartel.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2020,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1688289,"enunciado":"No que concerne à estruturação linguístico-gramatical do texto, julgue o item.\n\n\n\n\nNo texto, o termo “esse” (linha 2) retoma “diversidade” (linha 1).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1688295,"enunciado":"No que concerne à estruturação linguístico-gramatical do texto, julgue o item.\n\nNo texto, a expressão “dos quais” (linha 25) retoma “esses jovens” (linha 24).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1688299,"enunciado":"Com relação às ideias do texto, julgue o item.\n\nConforme o texto, a desigualdade social é resultado do desinteresse dos cidadãos pelas políticas públicas educacionais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1688301,"enunciado":"Com relação às ideias do texto, julgue o item.\n\nDe acordo com o texto, os adolescentes e jovens que estão em defasagem educacional, não lhes sendo garantido o direito fundamental à educação, apresentam baixos níveis de aprendizagem escolar ou abandonaram a escola com baixo nível de instrução formal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1700594,"enunciado":"A respeito das ideias do texto, julgue o item.\n\n\n\n\nA ideia central do texto explora a relação entre a alimentação consumida e a dimensão temporal proposta pelo movimento Slow Food.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1700597,"enunciado":"A respeito das ideias do texto, julgue o item.\n\n\n\n\nConforme o texto, o Slow Food é um movimento retrógrado, que atribui grande importância à tradição, a qual mantém a confiança na continuidade do passado, do presente e do futuro e a vincula às práticas sociais rotinizadas, tais como a alimentação da vida moderna.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1748460,"enunciado":"Com relação às ideias e aos aspectos linguísticos do texto, julgue o item.\n\nDe acordo com o texto, Aristóteles acreditava que o cérebro teria papel secundário no funcionamento do corpo humano.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1782134,"enunciado":"Com relação às ideias  suscitadas pelo  texto, julgue o item.\n\n\n\n\nConforme o texto, existem causas diversas para o surgimento de doenças, inclusive  as de natureza social.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1782141,"enunciado":"Julgue o item quanto à estruturação linguística do  texto.\n\n\n\n\nNa linha 6, sem prejuízo para a correção gramatical e os sentidos originais do texto, a sentença “o que acarreta”, que retoma toda a oração anterior, pode ser substituída pela forma acarretando.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1783778,"enunciado":"De acordo com o texto, as pessoas economicamente desfavorecidas, como trabalhadores informais e desempregados, são mais suscetíveis à covid-19.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1844355,"enunciado":"Considerando as ideias e os sentidos do texto apresentado, julgue o item.\n\n\n\n\nDe acordo com o texto, só no ano de 1849 o petróleo foi descoberto, por isso, até então, a madeira e o carvão mineral eram usados como fontes de energia.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2021,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1907269,"enunciado":"Considerando as ideias, os sentidos e os aspectos linguísticos do texto apresentado, julgue o item.  \n\n\n\n\nDe acordo com o texto, a ciência, por muito tempo, não conseguiu responder se cães têm consciência da intenção dos humanos, mas o estudo liderado por Britta Schünemann encerrou o debate científico sobre o assunto ao fornecer uma resposta afirmativa a essa indagação.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1907273,"enunciado":"Considerando as ideias, os sentidos e os aspectos linguísticos do texto apresentado, julgue o item.  \n\n\n\n\nDe acordo com o texto, o estudo liderado pelas psicólogas alemãs confirmou a intuição de outros pesquisadores da área que também estudavam o comportamento canino.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1909165,"enunciado":"Acerca das estruturas linguísticas do texto CG2A1-I, julgue o item a seguir.\nA correção e o sentido do texto seriam mantidos se, no último parágrafo, a forma verbal “há” fosse substituída por existem.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2022,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1917705,"enunciado":"Com relação às ideias do texto, julgue o item. \n\n\n\n\nSegundo o texto, na atualidade os homens geralmente são vaidosos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1939942,"enunciado":"Em relação às ideias do texto, julgue o item. \n\n\n\n\nDe acordo com o texto, que é estruturado em forma dissertativa, as empresas brasileiras só começaram a se preocupar com a saúde mental de seus colaboradores durante a pandemia de covid-19, quando milhares de pessoas pediram afastamento do trabalho por transtornos mentais e comportamentais.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1955630,"enunciado":"Em relação à tipologia do texto e às ideias nele expressas, julgue o item.\n\n\n\n\nDe acordo com o texto, por serem descartáveis, problemas genéticos, psiquiátricos e auditivos não são investigados nos exames clínicos relacionados ao atraso no desenvolvimento da fala.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":1976615,"enunciado":"Em relação às ideias e aos aspectos linguísticos do texto apresentado, julgue o item. \n\nDe acordo com o texto, a função da dor deve sempre ser ignorada.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2003198,"enunciado":"Com relação às ideias e aos aspectos linguísticos e estruturais do texto, julgue o item.\n\n\n\n\nO  elemento  “Isso”  (linha  22)  retoma  todo  o  período  anterior, iniciado na linha 16.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2019,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2017378,"enunciado":"Considerando os aspectos linguísticos e as ideias do texto, julgue o item.\n\n\n\n\nSegundo o texto, o aborrecimento do repórter decorre do fato de ele necessitar de uma resposta e não a obter.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2022,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2077734,"enunciado":"Acerca do texto e de seus aspectos semânticos e linguísticos, julgue o item.\n\nDe acordo com o texto, o novo serviço público deve ser norteador e promotor de valores sociais como cidadania e democracia, todavia isso estaria estritamente ligado a um trabalho conjunto de diversas entidades sociais em interesse comum.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2134697,"enunciado":"Em relação ao texto e a seus aspectos linguísticos, julgue o item. \n\n\n\n\nDe acordo com o texto, há uma grande diferença entre ser e estar feliz, visto que a felicidade não é um sentimento permanente, mas, tão somente, uma das emoções que se pode sentir ao longo do dia.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2181002,"enunciado":"Acerca das ideias e dos aspectos gramaticais do texto, julgue o item abaixo.\nO último período do texto – “Além de uma possível insatisfação com a aparência, o acúmulo de gordura corporal pode levar à pessoa doenças graves, como hipertensão e outras cardiopatias.” – poderia ser reescrito, sem prejuízo para a correção gramatical nem para o sentido do texto, da seguinte forma: Além de uma possível insatisfação com a aparência, o acúmulo de gordura corporal pode levar a pessoa a doenças graves, como hipertensão e outras cardiopatias.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2183471,"enunciado":"Considerando a estrutura e os aspectos linguísticos do texto, julgue o item.\n\n\n\n\nA substituição de “mas” (linha 10) por porém não causaria prejuízo à correção gramatical nem ao sentido do texto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2249449,"enunciado":"De acordo com o texto acima, julgue o item a seguir.\n\n\n\n\nOs particípios verbais “tombado” (l.2), “Construído” (l.2), “Projetado” (l.4) e “Reinaugurado” (l.10) remetem ao mesmo sujeito da passiva: “O prédio do Departamento de Ordem Pública e Social” (l.1-2).","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2004,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2267013,"enunciado":"Segundo o texto, o movimento slow food defende uma relação de prazer com a alimentação, a preparação de refeições em casa, o consumo de alimentos locais e orgânicos, a preservação da biodiversidade e a educação do paladar.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2286820,"enunciado":"Acerca das ideias, dos sentidos e das propriedades linguísticas do texto, julgue o item.\n\n\n\n\nDe acordo com o texto, a repetição é algo positivo para o ser humano, pois oferece tranquilidade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2286822,"enunciado":"Acerca das ideias, dos sentidos e das propriedades linguísticas do texto, julgue o item.\n\n\n\n\nDe acordo com o texto, o mau hábito está fundamentado na passividade e no repouso, isto é, em fazer algo sempre do mesmo modo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2320390,"enunciado":"Considerando o texto e seus aspectos linguísticos, julgue o item a seguir.\n\nDe acordo com o texto, a biblioteca de Alexandria foi muito importante para a humanidade, mas, infelizmente, todo o acervo e os registros documentais foram perdidos devido a um incêndio de origem misteriosa.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2320392,"enunciado":"Considerando o texto e seus aspectos linguísticos, julgue o item a seguir.\n\nA expressão “Como tal” (linha 10), no contexto em que se insere, faz referência a um fato mencionado anteriormente, ao de que o incêndio na biblioteca foi uma perda enorme para a humanidade e inúmeras obras foram destruídas e queimadas.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2356214,"enunciado":"Em relação ao texto e às ideias nele expressas, julgue o item.\n\n\n\n\nDe acordo com o texto, o acúmulo de placa bacteriana causa gengivite e periodontite.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2358033,"enunciado":"Com base nos sentidos e nas ideias expressos no texto CB1A1, julgue o item a seguir.\n\n\n\n\nSegundo o texto, a desigualdade social que é refletida na arquitetura pode ser observada na coexistência, possivelmente na mesma cidade, de obras inteiramente elaboradas por IA e obras feitas com papel e lápis, sem a participação de arquitetos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2360374,"enunciado":"Acerca da tipologia, dos sentidos do texto e dos aspectos linguísticos, julgue o item.\n\n\n\n\nO termo “em particular” (linha 24) está empregado no mesmo sentido de especialmente, principalmente e sobretudo, podendo ser substituído por quaisquer uma das três palavras, pois o sentido original e a correção gramatical do texto seriam mantidos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2023,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2393889,"enunciado":"Julgue o item que se segue, com base nas ideias veiculadas no texto CG2A1.\n\n\n\n\nDe acordo com o texto, a discussão sobre a importância da igualdade de gênero, do combate à violência e da garantia dos direitos de meninas e mulheres foi intensificada em todos os continentes a partir da celebração do Dia Internacional das Mulheres pela ONU.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2393896,"enunciado":"Julgue o item que se segue, relativo a aspectos linguísticos do texto CG2A1.\n\n\n\n\nNo segundo período do terceiro parágrafo, a forma verbal “anuísse” tem o mesmo sentido de assentisse.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2415241,"enunciado":"Julgue o item que se segue, a respeito das ideias e estruturas linguísticas do texto precedente.\n\n\n\n\nSegundo o texto, o estudo da história social da ignorância envolveria descobrir as pessoas que ignoram algo em determinado espaço e em determinada época, o objeto da ignorância dessas pessoas, as causas dessa ignorância e seus efeitos.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2445465,"enunciado":"Com base nas ideias do texto, julgue o item.\n\n\n\n\nDe acordo com o texto, o transtorno de ansiedade ocorre com mais frequência durante a infância.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2445468,"enunciado":"Com base nas ideias do texto, julgue o item.\n\n\n\n\nDe acordo com o texto, os transtornos de ansiedade atingem igualmente ambos os sexos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2445469,"enunciado":"Com base nas ideias do texto, julgue o item.\n\n\n\n\nSegundo o texto, quando uma criança deixa de fazer coisas ou de ter uma atividade rotineira normal, isso pode gerar ansiedade.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2445470,"enunciado":"Com base nas ideias do texto, julgue o item.\n\n\n\n\nDe acordo com o texto, é normal que situações que envolvam viagens, festas de aniversário ou apresentação na escola causem ansiedade em crianças.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2445478,"enunciado":"Com base nas ideias e na estrutura do texto, julgue o item.\n\n\n\n\nDe acordo com o texto, dados da OMS revelam que a pandemia de covid‑19 foi a principal causa do aumento dos casos de ansiedade e de depressão desde o ano de 2020.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2445479,"enunciado":"Com base nas ideias e na estrutura do texto, julgue o item.\n\n\n\n\nDe acordo com o texto, a solidão e as preocupações financeiras são causas recorrentes de suicídio entre os profissionais de saúde.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2445482,"enunciado":"Em relação à estrutura linguística, ao vocabulário e aos mecanismos de coesão empregados no texto, julgue o item.\n\n\n\n\nA substituição da expressão “sem precedentes” (linha 6) pela palavra desconhecido manteria o sentido do texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2505033,"enunciado":"Quanto à estrutura linguística do texto, julgue o item abaixo.\n\nCaso a forma verbal “há” (linha 11) fosse substituída por existe, a correção e o sentido do texto seriam mantidos.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2505034,"enunciado":"Quanto à estrutura linguística do texto, julgue o item abaixo.\n\nA substituição da expressão “a qual” (linha 20) por onde manteria a correção e o sentido do texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2505036,"enunciado":"Com base nas ideias do texto, julgue o item que se segue.\n\nDe acordo com o texto, a condição para a poluição plástica ser reduzida em 80% até 2040 é que os países e as empresas façam mudanças profundas nas políticas e no mercado.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2505039,"enunciado":"Com base nas ideias do texto, julgue o item que se segue.\n\nDe acordo com o texto, os custos de investimento para a mudança sistêmica recomendada são de cerca de 113 bilhões de dólares por ano.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2505040,"enunciado":"Com base nas ideias do texto, julgue o item que se segue.\n\nConforme o texto, a eliminação de plásticos problemáticos e desnecessários vai acabar de vez com o problema da poluição plástica.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2505042,"enunciado":"Acerca da estrutura linguística do texto, julgue o item abaixo.\n\nA substituição da palavra “reduzida” (linha 1) por diminuída manteria a correção e o sentido do texto.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2528783,"enunciado":"Com base nas ideias apresentadas no texto, julgue o item que se segue.\n\n\n\n\nDe acordo com o texto, países como Áustria, Alemanha, Suíça, França, Portugal e Espanha já avançaram no que diz respeito a direito animal.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2528784,"enunciado":"Com base nas ideias apresentadas no texto, julgue o item que se segue.\n\n\n\n\nSegundo o texto, na legislação brasileira, os animais são tidos como objetos de direito.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2562849,"enunciado":"Com base nas ideias do texto, julgue o item a seguir. \n\nDe acordo com o texto, as mulheres grávidas costumam se preocupar muito com a própria saúde e com a saúde de seus bebês.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2562852,"enunciado":"Com base nas ideias do texto, julgue o item a seguir. \n\n\n\n\n\nDe acordo com o texto, as alterações nos dentes da mulher durante a gestação são decorrentes de desequilíbrios relacionados aos processos de desmineralização e de remineralização.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2665165,"enunciado":"Com base nas ideias do texto, julgue o item a seguir. \n\nSegundo o texto, um mesmo odor pode ser percebido de diferentes formas, a depender das características genéticas das pessoas que o sentem.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":2665172,"enunciado":"De acordo com a estrutura linguística do texto e com sua tipologia, julgue o item a seguir.\n\nO vocábulo “alocada” (linha 22) tem, no texto, o mesmo sentido de colocada, disposta.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3028199,"enunciado":"De acordo com o texto, os personagens eram:","opcoes":["pessoas totalmente sem vaidade.","pessoas que se odiavam mutuamente.","pessoas com parentesco consanguíneo.","pessoas que estavam com saudades uma da outra.","pessoas que haviam se relacionado romanticamente."],"correta":4,"explicacao":"Gabarito: <strong>pessoas que haviam se relacionado romanticamente.</strong>.","banca":"IBADE","ano":2024,"temas_relacionados":["interpretacaoTextos"]},{"id":3059916,"enunciado":"Com base nas ideias do texto, julgue o item seguinte.\n\n\n\n\nDe acordo com o texto, o surgimento do conceito de arquitetura hostil teve como base a teoria das janelas quebradas.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3059925,"enunciado":"Com base na estrutura linguística e no vocabulário empregados no texto, julgue o item a seguir.\n\n\n\n\nO nome “transeuntes” (linha 10) tem, no texto, o mesmo sentido de pedestres.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3059926,"enunciado":"Com base na estrutura linguística e no vocabulário empregados no texto, julgue o item a seguir.\n\n\n\n\nA substituição da expressão “com o fim de” (linha 12) por afim de manteria a correção gramatical e o sentido do texto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3059930,"enunciado":"Com base na estrutura linguística e no vocabulário empregados no texto, julgue o item a seguir.\n\n\n\n\nO sentido do texto seria mantido com a substituição da palavra “excludente” (linha 38) pela palavra exclusivo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3122287,"enunciado":"De acordo com o texto, julgue o item a seguir.\n\n\n\n\nNa linha 6, a forma verbal “desaparecerem” concorda corretamente com “a tecnologia”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3122294,"enunciado":"De acordo com o texto, julgue o item a seguir.\n\n\n\n\nA expressão “pela informação” (linhas 45 e 46) é um agente da passiva.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3122295,"enunciado":"De acordo com o texto, julgue o item a seguir.\n\n\n\n\nNa linha 50, o sujeito de “existem” está posposto em relação ao verbo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2024,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3198368,"enunciado":"De acordo com o texto, julgue o item a seguir.\n\n\n\n\nNo título, o vocábulo “escondidos” deveria concordar com “Dentista”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3198370,"enunciado":"De acordo com o texto, julgue o item a seguir.\n\n\n\n\nNa linha 7, a expressão “a suspeita” participa de um processo coesivo.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3198371,"enunciado":"De acordo com o texto, julgue o item a seguir.\n\n\n\n\nNa linha 7, a locução “iria prestar” poderia ser substituída, no contexto, sem prejuízo para o sentido, por “prestava”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3198373,"enunciado":"De acordo com o texto, julgue o item a seguir.\n\n\n\n\nNa linha 16, a locução “foi registrado” participa de uma construção de voz passiva.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3198374,"enunciado":"De acordo com o texto, julgue o item a seguir.\n\n\n\n\nNa linha 21, o termo “ao crime organizado” funciona, sintaticamente, como objeto indireto.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3198375,"enunciado":"De acordo com o texto, julgue o item a seguir.\n\n\n\n\nNa oração “e 170 celulares apreendidos” (linha 24), está subentendida a forma verbal “foram”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3390489,"enunciado":"Com base nas ideias do texto, julgue o item a seguir\n\n\n\n\nDe acordo com o texto, a vigilância sanitária foi o primeiro campo de atuação sistemática do médico veterinário na saúde pública.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3390491,"enunciado":"Com base nas ideias do texto, julgue o item a seguir\n\n\n\n\nConforme o texto, nos últimos tempos, o médico veterinário tem ocupado posições relevantes dentro das equipes de vigilância epidemiológica e ambiental, uma necessidade para a consolidação dessa carreira.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3390493,"enunciado":"No que se refere à estruturação linguística do texto anterior, julgue o seguinte item.\n\n\n\n\nNo primeiro parágrafo, no trecho “Desde que foram estabelecidos padrões de convivência coletiva, os seres humanos têm lutado contra as enfermidades que põem em risco a saúde dos seus animais. No entanto, muitas das doenças que dizimaram os seus rebanhos também foram responsáveis pela morte de milhares de pessoas.”, em ambas as ocorrências, o vocábulo “seus” retoma, diretamente, a expressão “milhares de pessoas”.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3505358,"enunciado":"Quanto a aspectos gerais do texto, julgue o item seguinte.\n\n\n\n\nNo trecho “De acordo com a Marinha, o acidente ocorreu na tarde desse sábado quando o médico, que pilotava o veículo, colidiu com os cabos de amarração de uma embarcação ancorada.”, a oração “que pilotava o veículo” é subordinada adjetiva, introduzida pelo relativo que retoma “médico”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3632483,"enunciado":"No que se refere à estruturação linguístico‑gramatical do texto, julgue o item seguinte.\n\nNo trecho “Freyre, ao comentar o tema, relata que o médico sueco Gustavo Beyer ficou impressionado com o que viu, ao adentrar o interior do Brasil”, a frase “ao comentar o tema” retoma a frase inicial do texto, ou seja, “O impacto de uma dieta cariogênica sobre as condições dentárias”.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2025,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":3951982,"enunciado":"Em relação ao texto e aos seus aspectos linguísticos, julgue o item a seguir.\n\n\n\n\nNo trecho “o transtorno já configura um problema de saúde pública”, a forma verbal “configura” é empregado com sentido equivalente a “caracteriza”","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"Quadrix","ano":2026,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":4120675,"enunciado":"Com base nas ideias veiculadas no texto CG7A1, julgue o item que se segue.\n\n\n\n\nDe acordo com o texto, os anos 1960 marcam o início das drásticas e definitivas mudanças no cenário ambiental global.","opcoes":["Certo","Errado"],"correta":1,"explicacao":"Gabarito: <strong>Errado</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":4120676,"enunciado":"Com base nas ideias veiculadas no texto CG7A1, julgue o item que se segue.\n\n\n\n\nDe acordo com o texto, a adesão dos órgãos públicos das esferas federal, estadual e municipal à A3P não é obrigatória.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]},{"id":4120686,"enunciado":"Julgue o seguinte item, referente às estruturas linguísticas e ao vocabulário empregados no texto CG7A1.\n\n\n\n\nNo trecho \"impactos ambientais adversos gerados pelas atividades administrativas\" (último parágrafo), o vocábulo \"adversos\" tem o mesmo sentido de prejudiciais.","opcoes":["Certo","Errado"],"correta":0,"explicacao":"Gabarito: <strong>Certo</strong>.","banca":"CESPE / CEBRASPE","ano":2026,"tipo":"certo_errado","temas_relacionados":["interpretacaoTextos"]}];
